  const worldTheme=world=>({异能都市:'city',古代修仙:'scroll',西幻:'jade'}[world]||'jade');
  const applyWorldTheme=world=>{const surface=state.mount?.querySelector('.xhcs-opening');if(surface)surface.dataset.theme=worldTheme(world);};
  const labelForWorld = key => {
    if (key === '异能都市') return '异能都市';
    if (key === '古代修仙') return '古代修仙';
    if (key === '西幻') return '西幻';
    return '尚未选择';
  };

  const getChatVars = () => {
    try {
      return getVariables({ type: 'chat' }) || {};
    } catch (error) {
      console.warn('[香火成神] 无法读取聊天变量', error);
      return {};
    }
  };

  const writeChatVar = (key, value) => {
    try {
      const variables = getChatVars();
      variables[key] = value;
      replaceVariables(variables, { type: 'chat' });
      const result = hostWindow.SillyTavern?.getContext?.()?.saveMetadata?.();
      if (result && typeof result.catch === 'function') {
        result.catch(error => console.warn('[香火成神] 聊天草稿保存失败', error));
      }
    } catch (error) {
      console.warn('[香火成神] 无法写入聊天变量', error);
    }
  };

  const loadDraft = () => {
    const saved = getChatVars()[DRAFT_KEY];
    return {
      version: 1,
      worldKey: saved?.worldKey || '',
      systemPersona: (saved?.systemPersona === '沙雕萝莉' ? '沙雕萌妹' : saved?.systemPersona) || '',
      divineName: saved?.divineName || '',
      divineGender: saved?.divineGender || '',
      appearance: saved?.appearance || '',
      background: saved?.background || '',
      visitorGender: saved?.visitorGender || '',
      visitorOther: saved?.visitorOther || '',
    };
  };

  const saveDraft = () => {
    if (!state.draft) return;
    writeChatVar(DRAFT_KEY, { ...state.draft });
  };

  const saveDraftDebounced = () => {
    hostWindow.clearTimeout(state.draftTimer);
    state.draftTimer = hostWindow.setTimeout(saveDraft, 250);
  };

  const getCommitted = () => {
    const committed = getChatVars()[COMMIT_KEY];
    return committed?.version === 1 && committed?.committed ? committed : null;
  };

  const getSubmitLock = () => {
    const lock = getChatVars()[SUBMIT_KEY];
    return lock?.version === 1 ? lock : null;
  };

  const setSubmitLock = (value) => writeChatVar(SUBMIT_KEY, value);

  const currentChatId = () => {
    try {
      const context = hostWindow.SillyTavern?.getContext?.();
      return [context?.characters?.[context?.characterId]?.avatar || 'xianghuo',context?.chatId || context?.getCurrentChatId?.() || ''].join(':');
    } catch (_) {
      return '';
    }
  };

  const currentUserName = () => {
    try {
      const context = hostWindow.SillyTavern?.getContext?.();
      return String(context?.name1 || hostWindow.SillyTavern?.name1 || '{{user}}');
    } catch (_) {
      return '{{user}}';
    }
  };

  const getLastMessageIdSafe = () => {
    try {
      if (typeof getLastMessageId === 'function') return Number(getLastMessageId());
      const rows = getChatMessages(-1);
      return Number(rows.at(-1)?.message_id ?? 0);
    } catch (_) {
      return 0;
    }
  };

  const withTimeout = (promise, timeoutMs, message) => new Promise((resolve, reject) => {
    const timer = hostWindow.setTimeout(() => reject(new Error(message)), timeoutMs);
    Promise.resolve(promise).then(
      value => {
        hostWindow.clearTimeout(timer);
        resolve(value);
      },
      error => {
        hostWindow.clearTimeout(timer);
        reject(error);
      },
    );
  });

  const waitForOpeningTurn = (beforeLastMessageId, timeoutMs = 180000) => withTimeout(
    new Promise((resolve, reject) => {
      const poll = hostWindow.setInterval(() => {
        try {
          const afterLastMessageId = getLastMessageIdSafe();
          if (afterLastMessageId <= beforeLastMessageId) return;
          const messages = getChatMessages(`${beforeLastMessageId + 1}-${afterLastMessageId}`, {
            hide_state: 'all',
            include_swipes: false,
          });
          const hasOpeningIntent = messages.some(row =>
            String(row.message || '').includes('【开局设定】')
            || JSON.stringify(row.extra || {}).includes('【开局设定】'));
          const hasUser = messages.some(row => row.role === 'user');
          const hasAssistant = messages.some(row => row.role === 'assistant');
          if (!hasOpeningIntent || !hasUser || !hasAssistant) return;
          hostWindow.clearInterval(poll);
          resolve(messages);
        } catch (error) {
          hostWindow.clearInterval(poll);
          reject(error);
        }
      }, 400);
    }),
    timeoutMs,
    '开局生成超过 3 分钟仍未完成',
  );

  const escapeHtml = (value) => String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');

  const personaChoicesTemplate = () => Object.entries(DATA.systemPersonas || {})
    .map(([name, meta]) => `
      <button class="xhcs-persona-choice" type="button" data-system-persona="${escapeHtml(name)}" aria-pressed="false">
        <span class="xhcs-persona-name">${escapeHtml(name)}</span>
