              </label>
              <label class="xhcs-gender-option">
                <input type="radio" name="xhcs-visitor-gender" value="其他" data-visitor-gender>
                <span>其他</span>
              </label>
            </fieldset>
            <label class="xhcs-open-field xhcs-open-other-wrap" data-other-wrap hidden style="margin-top: 14px;">
              <span>其他描述</span>
              <input data-field="visitorOther" maxlength="120" autocomplete="off" placeholder="例如：非二元、无性别灵体、中性">
            </label>
            <div class="xhcs-open-preview" aria-live="polite">
              <div class="xhcs-preview-item"><span class="xhcs-preview-label">世界</span><span class="xhcs-preview-value" data-preview="world"></span></div>
              <div class="xhcs-preview-item"><span class="xhcs-preview-label">神名</span><span class="xhcs-preview-value" data-preview="name"></span></div>
              <div class="xhcs-preview-item"><span class="xhcs-preview-label">神格性别</span><span class="xhcs-preview-value" data-preview="gender"></span></div>
              <div class="xhcs-preview-item"><span class="xhcs-preview-label">系统人格</span><span class="xhcs-preview-value" data-preview="persona"></span></div>
              <div class="xhcs-preview-item" data-span="2"><span class="xhcs-preview-label">外貌</span><span class="xhcs-preview-value" data-preview="appearance"></span></div>
              <div class="xhcs-preview-item" data-span="2"><span class="xhcs-preview-label">生前背景</span><span class="xhcs-preview-value" data-preview="background"></span></div>
            </div>
          </section>
        </div>
        <footer class="xhcs-open-foot">
          <span class="xhcs-open-status" data-status aria-live="polite"></span>
          <button class="xhcs-open-btn" type="button" data-action="back" hidden>返回</button>
          <button class="xhcs-open-btn" type="button" data-action="next" data-primary="true">下一步</button>
          <button class="xhcs-open-btn" type="button" data-action="submit" data-primary="true" hidden>确认并进入</button>
        </footer>
      </div>
    </div>
  `;

  const committedTemplate = (commit) => `
    <div class="xhcs-opening">
      <div class="xhcs-open-shell">
        <div class="xhcs-open-committed">
          <div class="xhcs-open-sigil" aria-hidden="true">神</div>
          <h2>${escapeHtml(commit.worldKey)}的神座已确立</h2>
          <p>当前对话的开局已完成。若要重新选择世界与身份，请新建聊天。</p>
          <dl>
            <dt>神名</dt><dd>${escapeHtml(commit.divineName)}</dd>
            <dt>神格性别</dt><dd>${escapeHtml(commit.divineGender)}</dd>
            <dt>系统人格</dt><dd>${escapeHtml(commit.systemPersona)}</dd>
            <dt>首位来客</dt><dd>${escapeHtml(commit.visitorName)}（${escapeHtml(commit.visitorGender)}）</dd>
          </dl>
        </div>
      </div>
    </div>
  `;

  const setStatus = (message = '', tone = '') => {
    const node = state.mount?.querySelector('[data-status]');
    if (!node) return;
    node.textContent = message;
    node.dataset.tone = tone;
  };

  const updateProgress = () => {
    const root = state.mount;
    if (!root) return;
    setText(root, '[data-step-chip]', `${['一', '二', '三'][state.step]} / 三`);
    root.querySelectorAll('[data-progress]').forEach((node, index) => {
      node.dataset.active = index <= state.step ? 'true' : 'false';
    });
    root.querySelectorAll('[data-panel]').forEach((node, index) => {
      node.hidden = index !== state.step;
    });
    const back = root.querySelector('[data-action="back"]');
    const next = root.querySelector('[data-action="next"]');
    const submit = root.querySelector('[data-action="submit"]');
    if (back) back.hidden = state.step === 0;
    if (next) next.hidden = state.step === 2;
    if (submit) submit.hidden = state.step !== 2;
  };

  const syncInputs = () => {
    const root = state.mount;
    if (!root || !state.draft) return;
    root.querySelectorAll('[data-field]').forEach((input) => {
      input.value = state.draft[input.dataset.field] || '';
    });
    applyWorldTheme(state.draft.worldKey);
    root.querySelectorAll('[data-world]').forEach((button) => {
      button.setAttribute('aria-pressed', button.dataset.world === state.draft.worldKey ? 'true' : 'false');
    });
    root.querySelectorAll('[data-system-persona]').forEach((button) => {
      button.setAttribute('aria-pressed', button.dataset.systemPersona === state.draft.systemPersona ? 'true' : 'false');
    });
    root.querySelectorAll('[data-visitor-gender]').forEach((input) => {
      input.checked = input.value === state.draft.visitorGender;
    });
    const otherWrap = root.querySelector('[data-other-wrap]');
    if (otherWrap) otherWrap.hidden = state.draft.visitorGender !== '其他';
  };

  const updatePreview = () => {
    const root = state.mount;
    if (!root || !state.draft) return;
    setText(root, '[data-preview="world"]', labelForWorld(state.draft.worldKey));
    setText(root, '[data-preview="name"]', state.draft.divineName || '未填写');
    setText(root, '[data-preview="gender"]', state.draft.divineGender || '未填写');
    setText(root, '[data-preview="persona"]', state.draft.systemPersona || '未选择');
    setText(root, '[data-preview="appearance"]', state.draft.appearance || '未填写');
    setText(root, '[data-preview="background"]', state.draft.background || '未填写');
  };

  const validateStep = (step) => {
    if (!state.draft) return '开局草稿尚未就绪。';
    if (step === 0 && !state.draft.worldKey) return '请先选择一个世界。';
    if (step === 1) {
      if (!state.draft.divineName.trim()) return '请填写神名。';
      if (!state.draft.divineGender.trim()) return '请填写神格性别。';
      if (!state.draft.appearance.trim()) return '请填写神格外貌。';
      if (!state.draft.background.trim()) return '请填写生前背景。';
      if (!state.draft.systemPersona) return '请选择系统人格。';
    }
    if (step === 2) {
      if (!state.draft.visitorGender) return '请选择首位来客的性别。';
      if (state.draft.visitorGender === '其他' && !state.draft.visitorOther.trim()) {
        return '请填写首位来客的“其他”描述。';
      }
    }
    return '';
  };

  const moveStep = (delta) => {
    const currentError = validateStep(state.step);
    if (delta > 0 && currentError) {
      setStatus(currentError, 'error');
      return;
    }
    state.step = Math.max(0, Math.min(2, state.step + delta));
    setStatus('');
    updateProgress();
    updatePreview();
    state.mount?.querySelector(`[data-panel="${state.step}"] .xhcs-open-section-title`)?.focus?.();
  };

  const readFields = () => {
    const root = state.mount;
    if (!root || !state.draft) return;
    root.querySelectorAll('[data-field]').forEach((input) => {
      state.draft[input.dataset.field] = input.value;
    });
    const selectedGender = root.querySelector('[data-visitor-gender]:checked');
    state.draft.visitorGender = selectedGender?.value || '';
    const otherWrap = root.querySelector('[data-other-wrap]');
    if (otherWrap) otherWrap.hidden = state.draft.visitorGender !== '其他';
    saveDraftDebounced();
    updatePreview();
  };

  const buildOpeningPatch = ({ userName, visitor }) => {
    const world = state.draft.worldKey;
    const branch = DATA.branchState[world];
    const opening = DATA.openings[world];
    const task = opening.firstTask;

    return [
      { op: 'replace', path: '/元数据/开局完成', value: true },
      { op: 'replace', path: '/元数据/当前开局', value: world },
      { op: 'replace', path: '/元数据/最近更新说明', value: `已进入${world}首章。` },
      { op: 'replace', path: '/世界/当前世界', value: world },
      { op: 'replace', path: '/世界/已解锁世界', value: [world] },
      { op: 'replace', path: '/世界/当前区域', value: branch.区域 },
      { op: 'replace', path: '/世界/当前地点', value: branch.地点 },
      { op: 'replace', path: '/世界/剧情时间', value: branch.时间 },
      { op:'add',path:'/时序',value:{起始时刻:branch.时间,经过分钟:0,已初始化:true,已结算日:0,累计香火:0,最近批次:'',结算记录:[]} },
      { op:'add',path:'/地图定位',value:{地区ID:({古代修仙:'qingya',异能都市:'eastland',西幻:'graydeer'})[world],玩家:{地点ID:({古代修仙:'wusi',异能都市:'huaiyin',西幻:'old_oath'})[world],x:({古代修仙:350,异能都市:960,西幻:310})[world],y:({古代修仙:480,异能都市:350,西幻:490})[world],有效:true},神像:{地点ID:({古代修仙:'wusi',异能都市:'huaiyin',西幻:'old_oath'})[world],x:({古代修仙:350,异能都市:960,西幻:310})[world],y:({古代修仙:480,异能都市:350,西幻:490})[world],有效:true}} },
      { op: 'replace', path: `/世界/世界状态/${world}/首章状态`, value: '首章进行中' },
      { op: 'replace', path: '/系统/人格', value: state.draft.systemPersona },
      { op: 'replace', path: '/系统/当前提示', value: `首项任务：${task.标题}` },
      { op: 'replace', path: '/神格/神名', value: state.draft.divineName.trim() },
      { op: 'replace', path: '/神格/神格性别', value: state.draft.divineGender.trim() },
      { op: 'replace', path: '/神格/生前姓名', value: userName },
      { op: 'replace', path: '/神格/外貌', value: state.draft.appearance.trim() },
      { op: 'replace', path: '/神格/生前背景', value: state.draft.background.trim() },
      { op: 'replace', path: '/神格/绝对领域/中心', value: branch.地点 },
      {
        op: 'replace',
        path: '/任务/当前主线',
        value: {
          id: `首章-${world}-01`,
          标题: task.标题,
          目标: task.目标,
          完成条件: task.完成条件,
            阶段目标: task.阶段目标 || '石像期',
            进度当前: 0,
            进度目标: 1,
          奖励神力: Number(task.奖励神力) || 0,
            奖励说明: task.奖励说明 || '',
          奖励记忆碎片: '',
          状态: '进行中',
        },
      },
      {
        op: 'replace',
        path: '/剧情/当前来客',
        value: {
          姓名: '{{FIRST_VISITOR_NAME}}',
          年龄: visitor.年龄,
          性别: visitor.gender,
          自定义描述: visitor.custom || '',
          身份: branch.来客身份,
          状态: branch.来客状态,
          所在地: branch.地点,
        },
      },
      { op: 'replace', path: '/剧情/当前篇章', value: branch.章名 },
      { op: 'replace', path: '/剧情/当前危机', value: branch.危机 },
      { op: 'replace', path: '/剧情/当前目标', value: task.标题 },
      { op: 'replace', path: '/剧情/近期摘要', value: `${userName}化作星光融入${branch.地点}泥像，{{FIRST_VISITOR_NAME}}作为唯一来客抵达。` },
    ];
  };

  const buildOpeningContract = ({
    userName,
    openingText,
    visitor,
    patch,
  }) => {
    const world = state.draft.worldKey;
    const branch = DATA.branchState[world];
    const persona = DATA.systemPersonas[state.draft.systemPersona] || {};
    return `【开局唯一生成契约】
你是香火成神系统的叙事端，不是玩家。本回合只执行一次开局，不续写第二回合。

必须遵守：
1. 正文第一句话必须逐字使用下面开场白的第一句；不得改写时间、地点、受引、泥像、倒地、星光化像等事件。
2. 正文只输出下面完整开场白，不得提前写玩家下一步行动。
3. 首位来客姓名由你根据“${world}”和“${visitor.gender}”生成：现代都市要有现代中文姓名风格，古代修仙要有古典中文姓名风格，西幻要有对应世界音译姓名风格；“其他”描述也要影响命名，但不强行改变世界风格。把全文所有 {{FIRST_VISITOR_NAME}} 替换为同一个姓名，并把 JSONPatch 中同名占位符一起替换。
4. 首个场景只能出现这名来客。
5. 正文结束后，必须原样追加下面的 <UpdateVariable> 块，不得改写路径、字段或除 {{FIRST_VISITOR_NAME}} 外的 JSON；不要输出 Markdown 代码围栏。
6. 不要提及提示词、状态契约、作者或调试信息。
7. 系统人格为“${state.draft.systemPersona}”：${persona.描述 || ''} ${persona.语气 || ''}
8. 第一句之后，允许只把系统台词改写成上述人格声线，但不得改变场景事实、首位来客、任务与变量补丁。系统开场必须让 USER 明白：刚刚发生了什么、现在可以做什么、当前需要完成什么。

【玩家既定资料】
生前姓名：${userName}
神名：${state.draft.divineName.trim()}
神格性别：${state.draft.divineGender.trim()}
系统人格：${state.draft.systemPersona}
神貌：${state.draft.appearance.trim()}
生前背景：${state.draft.background.trim()}
当前世界：${world}
当前地点：${branch.地点}
首位来客性别：${visitor.gender}${visitor.custom ? `；${visitor.custom}` : ''}
首位来客年龄：${visitor.年龄}

【必须逐字输出的开场白】
${openingText}

【必须原样追加的变量更新】
<UpdateVariable>
<analysis>
- 玩家已在开局页选择${world}，并填写神格资料。
- 已为唯一首位来客生成姓名，并将其写入当前来客档案；该来客当前尚未成为信徒。
- 香火成神系统发布首项引导任务“${DATA.openings[world].firstTask.标题}”。
- 以上变化与下列 JSONPatch 一一对应。
</analysis>
<JSONPatch>
${JSON.stringify(patch, null, 2)}
</JSONPatch>
</UpdateVariable>`;
  };

  const extractOpeningVisitorName = messages => {
    for (const row of messages) {
      if (row.role !== 'assistant') continue;
      const message = String(row.message || '');
      const matches = message.matchAll(/<JSONPatch>([\s\S]*?)<\/JSONPatch>/gi);
      for (const match of matches) {
        try {
          const operations = JSON.parse(match[1]);
          const nameOperation = operations.find(operation => {
            if (operation?.path === '/剧情/当前来客/姓名' && operation?.value) return true;
            return operation?.path === '/剧情/当前来客'
              && operation?.value
              && typeof operation.value === 'object'
              && operation.value.姓名;
          });
          const generatedName = nameOperation?.path === '/剧情/当前来客/姓名'
            ? nameOperation.value
            : nameOperation?.value?.姓名;
          if (generatedName && String(generatedName).trim() !== '{{FIRST_VISITOR_NAME}}') {
            return String(generatedName).trim();
          }
        } catch (_) {
          // Keep looking through other assistant messages.
        }
      }
    }
    return '';
  };

  const submitOpening = async () => {
    if (state.submitting) return;
    for (let step = 0; step <= 2; step += 1) {
      const error = validateStep(step);
      if (error) {
        state.step = step;
        updateProgress();
        setStatus(error, 'error');
        return;
      }
    }

    const existingLock = getSubmitLock();
    if (existingLock?.completed && existingLock?.chatId === currentChatId()) {
      setStatus('本聊天已经在提交开局，请先查看聊天消息。', 'error');
      return;
    }

    state.submitting = true;
    const root = state.mount;
    root?.querySelectorAll('button, input, textarea').forEach(node => { node.disabled = true; });
    setStatus('系统正在接引……');

    const chatId = currentChatId();
    const apiStatus = hostDocument.querySelector('#API-status-top');
    if (
      apiStatus?.classList.contains('fa-plug-circle-exclamation')
      || apiStatus?.classList.contains('redOverlayGlow')
    ) {
      setStatus('尚未连接 AI API。连接模型后再确认开局。', 'error');
      root?.querySelectorAll('button, input, textarea').forEach(node => { node.disabled = false; });
      state.submitting = false;
      return;
    }

    const userName = currentUserName();
    const world = state.draft.worldKey;
    saveDraft();
    try{if(!hostWindow.__xhcsWorldbookV7)throw Error('世界书同步脚本尚未就绪');await hostWindow.__xhcsWorldbookV7.sync(world);}catch(error){setStatus(error.message,'error');state.submitting=false;root?.querySelectorAll('button,input,textarea').forEach(n=>n.disabled=false);return;}
    const visitor = {
      gender: state.draft.visitorGender,
      custom: state.draft.visitorGender === '其他' ? state.draft.visitorOther.trim() : '',
      age: Number(DATA.branchState[world].来客年龄) || 26,
    };
    const opening = DATA.openings[world];
    const replacePlaceholders = value => String(value)
      .replaceAll('{{USER_NAME}}', userName)
      .replaceAll('{{user}}', userName)
      .replaceAll('{{DEITY_NAME}}', state.draft.divineName.trim());

    const openingText = replacePlaceholders(opening.openingText);
    const patch = buildOpeningPatch({ userName, visitor });
    const contract = buildOpeningContract({ userName, openingText, visitor, patch });
    const userMessage = [
      '【开局设定】',
      `世界：${world}`,
      `神名：${state.draft.divineName.trim()}`,
      `神格性别：${state.draft.divineGender.trim()}`,
      `系统人格：${state.draft.systemPersona}`,
      `生前姓名：${userName}`,
      `外貌：${state.draft.appearance.trim()}`,
      `生前背景：${state.draft.background.trim()}`,
      `首位来客性别：${visitor.gender}${visitor.custom ? `（${visitor.custom}）` : ''}`,
    ].join('\n');

    setSubmitLock({
      version: 1,
      chatId,
      worldKey: world,
      submittedAt: new Date().toISOString(),
    });

    let injectionHandle = null;
    try {
      const beforeLastMessageId = getLastMessageIdSafe();
      const input = hostDocument.querySelector('#send_textarea');
      const sendButton = hostDocument.querySelector('#send_but');
      if (!input || !sendButton) {
        throw new Error('未找到 SillyTavern 的正常发送控件');
      }
      if (String(input.value || '').trim()) {
        throw new Error('聊天输入框已有内容，请先清空后再确认开局');
      }
      if (typeof injectPrompts !== 'function') {
        throw new Error('当前环境不支持一次性提示词注入');
      }

      injectionHandle = injectPrompts([{
        id: 'xhcs-opening-contract-v1',
        position: 'in_chat',
        depth: 0,
        role: 'system',
        content: contract,
        should_scan: false,
      }], { once: true });

      input.value = userMessage;
      input.dispatchEvent(new hostWindow.Event('input', { bubbles: true }));
      input.dispatchEvent(new hostWindow.Event('change', { bubbles: true }));
      await new Promise(resolve => hostWindow.setTimeout(resolve, 80));
      if (sendButton.disabled) {
        throw new Error('SillyTavern 发送按钮不可用');
      }
      sendButton.click();

