    const list=createEl('div','');list.dataset.role='ranks';dialog.append(list);hostDocument.body.append(dialog);
    renderRanks(dialog,data);
    dialog.addEventListener('close',()=>{dialog.remove();opener?.focus({preventScroll:true});},{once:true});
    dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dialog.close();}});
    dialog.showModal();close.focus();
  };
