.xhcs-character-text {display:block;width:100%;height:45vh;min-height:220px;resize:vertical;box-sizing:border-box;padding:14px;background:#fff9e9;color:#34483c;border:1px solid #b8b79c;border-radius:6px;font:14px/1.8 'Microsoft YaHei',sans-serif}
.xhcs-character-actions {display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}
.xhcs-character-actions button {padding:8px 12px;min-height:42px;border:1px solid #83947d;border-radius:6px;background:#405b48;color:#fff5dc;cursor:pointer;font:14px 'Microsoft YaHei',sans-serif}
.xhcs-character-actions button:disabled {opacity:.5;cursor:default}
.xhcs-character-dialog details p {white-space:pre-wrap;background:#eae2cb;padding:10px;border-radius:5px;font-size:12px}

.xhcs-hud .xhcs-person-head{flex-wrap:wrap;gap:6px}
.xhcs-hud .xhcs-person-name{min-width:0;overflow-wrap:anywhere;flex:1 1 5em}

      @media(prefers-reduced-motion:reduce) {.xhcs-hud * {animation:none!important;transition:none!important}}
    `;
    hostDocument.head.appendChild(style);
  };

  const staticShell = () => `
    <div class="xhcs-hud-head">
      <div class="xhcs-hud-brand"><button type="button" class="xhcs-hud-sigil xhcs-rank-trigger" data-role="stage" aria-label="查看神格段位"></button>
        <div><h3 class="xhcs-hud-title" data-role="god-name"></h3><p class="xhcs-hud-subtitle" data-role="location"></p></div>
      </div><label class="xhcs-theme-label">配色 <select data-theme-choice aria-label="状态栏配色"><option value="jade">墨绿</option><option value="scroll">古卷</option><option value="city">都市</option></select></label>
    </div>
    <div class="xhcs-stat-grid">
      <div class="xhcs-stat"><span class="xhcs-stat-label">神力积分</span><strong class="xhcs-stat-value" data-role="power"></strong><span class="xhcs-stat-detail" data-role="income"></span></div>
      <div class="xhcs-stat"><span class="xhcs-stat-label">信众</span><strong class="xhcs-stat-value" data-role="followers"></strong><span class="xhcs-stat-detail" data-role="faith-split"></span></div>
      <div class="xhcs-stat"><span class="xhcs-stat-label">领域半径</span><strong class="xhcs-stat-value" data-role="domain"></strong><span class="xhcs-stat-detail" data-role="domain-center"></span></div>
    </div>
    <nav class="xhcs-nav" role="tablist" aria-label="神域档案">
      <button type="button" role="tab" data-tab="now" aria-selected="true">此刻</button>
      <button type="button" role="tab" data-tab="powers" aria-selected="false" tabindex="-1">权柄</button>
      <button type="button" role="tab" data-tab="records" aria-selected="false" tabindex="-1">信众</button>
      <button type="button" role="tab" data-tab="deity" aria-selected="false" tabindex="-1">神格</button>
      <button type="button" role="tab" data-tab="map" aria-selected="false" tabindex="-1">地图</button>
    </nav>
    <div data-view="now" role="tabpanel" tabindex="0">
      <div class="xhcs-context" data-role="context"></div>
      <div class="xhcs-task-board" data-role="tasks"></div>
    </div>
    <div data-view="powers" role="tabpanel" tabindex="0" hidden><div class="xhcs-power-list" data-role="powers"></div></div>
    <div data-view="records" role="tabpanel" tabindex="0" hidden><div class="xhcs-hud-archive" data-role="records"></div></div>
    <div data-view="deity" role="tabpanel" tabindex="0" hidden>
      <div class="xhcs-context xhcs-deity" data-role="deity"></div>
      <div class="xhcs-progress-box"><div class="xhcs-progress-row"><span class="xhcs-progress-title" data-role="promotion-title"></span></div>
        <div class="xhcs-progress-track" role="progressbar" aria-label="晋升数量条件" aria-valuemin="0" aria-valuemax="100"><div class="xhcs-progress-fill" data-role="promotion-fill"></div></div>
        <div class="xhcs-progress-copy" data-role="promotion-copy"></div>
      </div><div class="xhcs-hud-archive" data-role="memories"></div>
    </div><div data-view="map" role="tabpanel" tabindex="0" hidden><div data-role="map"></div></div>
  `;

  const bindNavigation = (panel, messageId) => {
    const tabs = [...panel.querySelectorAll('[data-tab]')];
    const activate = tab => {
      tabs.forEach(button => { const selected = button === tab; button.setAttribute('aria-selected', String(selected)); button.tabIndex = selected ? 0 : -1; });
      panel.querySelectorAll('[data-view]').forEach(view => { view.hidden = view.dataset.view !== tab.dataset.tab; });
    };
    tabs.forEach((button, index) => {
      const view = panel.querySelector(`[data-view="${button.dataset.tab}"]`);
      button.id = `xhcs-tab-${messageId}-${button.dataset.tab}`;
      view.id = `xhcs-view-${messageId}-${button.dataset.tab}`;
      button.setAttribute('aria-controls', view.id); view.setAttribute('aria-labelledby', button.id);
      button.addEventListener('click', () => activate(button));
      button.addEventListener('keydown', event => {
        const keys = { ArrowRight:(index + 1) % tabs.length, ArrowLeft:(index + tabs.length - 1) % tabs.length, Home:0, End:tabs.length - 1 };
        if (!(event.key in keys)) return;
        event.preventDefault(); const next = tabs[keys[event.key]]; activate(next); next.focus();
      });
    });
  };

  const renderContext = (root, role, fields) => {
    const target = root.querySelector(`[data-role="${role}"]`);
    target.replaceChildren();
    fields.forEach(([label, value]) => {
      if (!text(value)) return;
      const row = createEl('div', 'xhcs-context-row'); row.append(createEl('b', '', label), createEl('span', '', text(value))); target.append(row);
    });
  };

  const setRoleText = (root, role, value) => {
    const node = root.querySelector(`[data-role="${role}"]`);
    if (node) node.textContent = text(value);
  };

  const renderPerson = (name, person) => {
    const level = text(person?.信仰等级);
    const age = number(person?.年龄);
    const box = createEl('details', 'xhcs-person');
    box.dataset.key = `person:${name}`;
    const head = createEl('summary', 'xhcs-person-head');
    head.append(
      createEl('strong', 'xhcs-person-name', text(person?.姓名) || name),
      createEl('span', 'xhcs-faith-badge', level || '信徒'),
    );
    head.prepend(avatarButton(person, name, box));
    const distill=createEl('button','xhcs-distill-button','提炼');distill.type='button';distill.onclick=event=>{event.preventDefault();event.stopPropagation();void distillCharacter(person,name).catch(error=>console.error('[香火成神] 提炼失败',error));};head.append(distill);
    box.append(head);

    const grid = createEl('div', 'xhcs-person-grid');
    const fields = [
      ['年龄', age ? `${age} 岁` : '未记录'],
      ['性别', person?.性别],
      ['身份', person?.身份],
      ['关系', person?.关系],
      ['亲近', person?.情感关系?.亲近阶段],
      ['公开身份', person?.情感关系?.公开身份],
      ['在意', person?.情感关系?.当前在意],
      ['所在地', person?.所在位置],
      ['当前状态', person?.当前状态],
      ['情绪', person?.情绪],
      ['外貌', person?.外貌],
      ['能力', Array.isArray(person?.能力) ? person.能力.join('、') : person?.能力],
      ['与神关系', person?.与神关系],
      ['近期经历', person?.近期经历],
    ];
    fields.forEach(([label, value]) => {
      if (!text(value)) return;
      const item = createEl('span', 'xhcs-kv');
      item.append(`${label}：`, createEl('b', '', text(value)));
      grid.append(item);
    });
    if (grid.childElementCount) box.append(grid);
    if(person?.情感关系?.关键事实?.length){const facts=createEl('details','');facts.append(createEl('summary','','关系事实'));person.情感关系.关键事实.forEach(f=>facts.append(createEl('p','xhcs-kv',`${text(f.摘要)} · 第${f.来源楼层}楼 / swipe ${f.来源swipe}`)));box.append(facts);}

    if (age >= 18 && person?.私密档案 && typeof person.私密档案 === 'object') {
      const privateBox = createEl('details', 'xhcs-private');
      privateBox.dataset.key = `private:${name}`;
      privateBox.append(createEl('summary', 'xhcs-private-title', '私密档案'));
      [
        ['乳房', person.私密档案.乳房],
        ['小穴', person.私密档案.小穴],
        ['后穴', person.私密档案.后穴],
      ].forEach(([label, value]) => {
        const item = createEl('span', 'xhcs-kv');
        item.append(`${label}：`, createEl('b', '', text(value) || '未记录'));
        privateBox.append(item);
      });
      box.append(privateBox);
    }

    return box;
  };

  const renderRecords = (root, data) => {
    const records = root.querySelector('[data-role="records"]');
    if (!records) return;
    records.replaceChildren();
    state.avatarIdentityCounts = new Map();
    [...Object.values(data?.重要人物 || {}), ...(Array.isArray(data?.普通信徒名录) ? data.普通信徒名录 : [])].forEach(person => { const id = [text(person?.姓名), person?.年龄 ?? '', person?.性别 ?? ''].join('|'); state.avatarIdentityCounts.set(id, (state.avatarIdentityCounts.get(id) || 0) + 1); });

    const important = data?.重要人物;
    if (important && typeof important === 'object' && !Array.isArray(important)) {
      Object.entries(important).forEach(([name, person]) => {
        if (!person) return;
        records.append(renderPerson(name, person));
      });
    }

    const ordinary = Array.isArray(data?.普通信徒名录) ? data.普通信徒名录 : [];
    if (ordinary.length) {
      const box = createEl('section', 'xhcs-person');
      box.append(createEl('strong', 'xhcs-person-name', '普通信徒名录'));
      const grid = createEl('div', 'xhcs-person-grid');
      ordinary.slice(0, 20).forEach((person) => {
        const parts = [
          text(person?.姓名),
          number(person?.年龄) ? `${number(person.年龄)}岁` : '',
          text(person?.身份),
          text(person?.所在地),
        ].filter(Boolean);
        if (parts.length) { const row = createEl('div', 'xhcs-person-head'); row.append(avatarButton(person, '', row), createEl('span', 'xhcs-kv', parts.join(' · ')));const distill=createEl('button','xhcs-distill-button','提炼');distill.type='button';distill.onclick=()=>void distillCharacter(person,'ordinary:'+text(person.姓名)).catch(console.error);row.append(distill); grid.append(row); }
      });
      if (grid.childElementCount) box.append(grid);
    if(person?.情感关系?.关键事实?.length){const facts=createEl('details','');facts.append(createEl('summary','','关系事实'));person.情感关系.关键事实.forEach(f=>facts.append(createEl('p','xhcs-kv',`${text(f.摘要)} · 第${f.来源楼层}楼 / swipe ${f.来源swipe}`)));box.append(facts);}
      records.append(box);
    }

    const memories = root.querySelector('[data-role="memories"]');
    memories.replaceChildren();
    const truth = data?.真相;
    const fragments = Array.isArray(truth?.记忆碎片) ? truth.记忆碎片 : [];
    if (text(truth?.认知阶段) && (text(truth.认知阶段) !== '毫无察觉' || fragments.length)) {
      const box = createEl('section', 'xhcs-person');
      box.append(createEl('strong', 'xhcs-person-name', '旧档案'));
      const grid = createEl('div', 'xhcs-person-grid');
      grid.append(createEl('span', 'xhcs-kv', `认知：${text(truth.认知阶段) || '毫无察觉'}`));
      if (fragments.length) grid.append(createEl('span', 'xhcs-kv', `记忆碎片：${fragments.length} 枚`));
      box.append(grid);
      const clues = Array.isArray(truth?.未解线索) ? truth.未解线索 : [];
      clues.forEach(clue => box.append(createEl('div', 'xhcs-kv', clue)));
      memories.append(box);
    }

    if (!records.childElementCount) {
      records.append(createEl('span', 'xhcs-empty', '尚无已记录的信徒档案。'));
    }
  };

  const renderPowers = (root, data) => {
    const list = root.querySelector('[data-role="powers"]');
    const summary = root.querySelector('[data-role="powers-summary"]');
    if (!list) return;
    list.replaceChildren();
    const stage = text(data?.神格?.神像阶段) || '未同步';
    const declared = new Set(
      Array.isArray(data?.神格?.已解锁能力) ? data.神格.已解锁能力.map(text) : [],
    );
    const powers = availablePowers(stage);
    declared.forEach(name => {
      if (name === '精神共鸣') return;
      if (!POWER_CATALOG.some(power => power.name === name)) {
        powers.push({ name, cost: '未记录', description: '该权柄由当前卡状态解锁，消耗以世界书规则为准。' });
      }
    });
    if (summary) summary.textContent = `当前权柄 · ${powers.length} 项`;
    powers.forEach(power => {
      const item = createEl('div', 'xhcs-power');
      const head = createEl('div', 'xhcs-power-head');
      head.append(
        createEl('strong', 'xhcs-power-name', power.name),
        createEl('span', 'xhcs-power-cost', power.cost),
      );
      item.append(head, createEl('span', 'xhcs-power-desc', power.description));
      list.append(item);
    });
    if (!powers.length) list.append(createEl('span', 'xhcs-empty', '暂无可用权柄。'));
  };

  const renderTaskBoard=(root,data)=>{
    const target=root.querySelector('[data-role=tasks]');target.replaceChildren();
    const main=data?.任务?.当前主线,side=(Array.isArray(data?.任务?.支线)?data.任务.支线:[]).filter(q=>q&&text(q.标题)).slice(0,2);
    const growth=task=>{const value=text(task?.阶段目标)||nextPromotion(data).label;return /宇宙/.test(value)?'当前系统权能不足，无法查看后续段位':value;};
    const appendTask=(mount,task,isMain)=>{
      const current=number(task.进度当前),goal=number(task.进度目标);
      const add=(label,value)=>{const row=createEl('div','xhcs-task-field');row.append(createEl('dt','',label),createEl('dd','',value));mount.append(row);};
      if(isMain)add('成长方向',growth(task));
      add('目标',text(task.目标)||'等待剧情发布');
      add('验收',text(task.完成条件)||'以正文实际结果为准');
      if(Number.isFinite(goal)&&goal>0&&Number.isFinite(current)){
        add('进度',`${formatNumber(current)} / ${formatNumber(goal)}`);
        const progress=createEl('progress','xhcs-task-progress');progress.max=goal;progress.value=Math.min(current,goal);progress.setAttribute('aria-label',`${text(task.标题)}的客观完成进度`);mount.append(progress);
      }
      const reward=number(task.奖励神力);
      add('完成奖励',[Number.isFinite(reward)?`${formatNumber(reward)}点神力`:'神力奖励未记录',text(task.奖励说明),text(task.奖励记忆碎片)?`记忆碎片：${text(task.奖励记忆碎片)}`:''].filter(Boolean).join(' · '));
    };
    const makeGroup=(kind,title,status,growthLabel,key)=>{
      const box=createEl('details',`xhcs-task-group xhcs-task-${kind}`);box.dataset.key=key;
      const summary=createEl('summary','xhcs-task-strip');
      summary.append(createEl('span','xhcs-task-kind',kind==='main'?'主线':'支线'),createEl('span','xhcs-task-strip-title',title),createEl('span','xhcs-task-state',status));
      if(growthLabel)summary.append(createEl('span','xhcs-task-growth',growthLabel));
      const content=createEl('div','xhcs-task-content');box.append(summary,content);target.append(box);return content;
    };
    const hasMain=main&&text(main.标题);
    const mainContent=makeGroup('main',hasMain?text(main.标题):'成长之路待发布',hasMain?text(main.状态)||'进行中':'未发布',hasMain?growth(main):'','task:main');
    if(hasMain){const fields=createEl('dl','xhcs-task-fields');appendTask(fields,main,true);mainContent.append(fields);}else mainContent.append(createEl('p','xhcs-task-empty',`当前${text(data?.神格?.神像阶段)||'阶段待同步'} · ${nextPromotion(data).label}。后续主线将围绕信仰、神迹与神域成长发布。`));
    const sideContent=makeGroup('side',side.length?side.map(q=>text(q.标题)).join(' / '):'暂无支线任务',`${side.length}项`,'','task:side');
    side.forEach(q=>{const box=createEl('details','xhcs-side-task');box.dataset.key=`quest:${q.id||q.标题}`;box.append(createEl('summary','',`${text(q.标题)} · ${text(q.状态)||'进行中'}`));const fields=createEl('dl','xhcs-task-fields');appendTask(fields,q,false);box.append(fields);sideContent.append(box);});
    if(!side.length)sideContent.append(createEl('p','xhcs-task-empty','支线随人物处境、地方危机与营建机会出现。'));
  };

  const renderHud = (root, data) => {
    const world = text(data?.世界?.当前世界) || '未选择';
    const area = text(data?.世界?.当前区域);
    const location = text(data?.世界?.当前地点);
    const stage = text(data?.神格?.神像阶段) || '未同步';
    const faith = data?.信仰 || {};
    const total = number(faith.普通信徒) + number(faith.核心信徒) + number(faith.狂热信徒);
    const income = number(faith.普通信徒) + number(faith.核心信徒) * 5 + number(faith.狂热信徒) * 20;
    const domainRadius = number(data?.神格?.绝对领域?.半径);
    const domainCenter = text(data?.神格?.绝对领域?.中心) || location || '神像所在处';
    const promotion = nextPromotion(data);

    setRoleText(root, 'god-name', text(data?.神格?.神名) || '香火成神系统');
    setRoleText(root, 'location', [world, area, location].filter(Boolean).join(' · '));
    renderContext(root, 'context', [
      ['时间', displayClock(data)],
      ['来客', [data?.剧情?.当前来客?.姓名, data?.剧情?.当前来客?.身份, data?.剧情?.当前来客?.状态].filter(Boolean).join(' · ')],
      ['危机', data?.剧情?.当前危机],
      ['目标', data?.剧情?.当前目标],
    ]);
    renderContext(root, 'deity', [
      ['神名', data?.神格?.神名], ['神格性别', data?.神格?.神格性别], ['外貌', data?.神格?.外貌],
      ['化身', data?.神格?.化身?.状态], ['所在地', data?.神格?.化身?.所在地],
    ]);
    setRoleText(root, 'stage', stage);
    setRoleText(root, 'power', formatNumber(data?.神格?.神力积分));
    setRoleText(root, 'income', `预计香火 +${formatNumber(income)} / 日`);
    setRoleText(root, 'followers', formatNumber(total));
    setRoleText(
      root,
      'faith-split',
      `普通 ${formatNumber(faith.普通信徒)} · 核心 ${formatNumber(faith.核心信徒)} · 狂热 ${formatNumber(faith.狂热信徒)}`,
    );
    setRoleText(root, 'domain', stage === '宇宙神像期' ? '全宇宙' : `${formatNumber(domainRadius)}${Number.isFinite(domainRadius) ? ' 米' : ''}`);
    setRoleText(root, 'domain-center', `中心：${domainCenter}`);
    setRoleText(root, 'promotion-title', promotion.label);
    setRoleText(root, 'promotion-copy', promotion.detail);
    const fill = root.querySelector('[data-role="promotion-fill"]');
    if (fill) {
      const percent = Math.round(promotion.progress * 100);
      fill.style.setProperty('--xhcs-progress', `${Number.isFinite(percent) ? percent : 0}%`);
      fill.parentElement.hidden = !Number.isFinite(percent);
      fill.parentElement.setAttribute('aria-valuenow', String(Number.isFinite(percent) ? percent : 0));
      fill.parentElement.setAttribute('aria-valuetext', promotion.detail);
    }

    renderTaskBoard(root,data);
    root.querySelector('[data-role=stage]').onclick=()=>showRankDialog(root,data,root.querySelector('[data-role=stage]'));
    renderMap(root,data);
    hostDocument.querySelectorAll('.xhcs-map-dialog').forEach(dialog=>renderMap(dialog,data));
    renderPowers(root, data);
    renderRecords(root, data);
  };

  const currentChatId = () => {
    try {
      const context = hostWindow.SillyTavern?.getContext?.();
      return [context?.characters?.[context?.characterId]?.avatar || 'xianghuo', context?.chatId || context?.getCurrentChatId?.() || ''].join(':');
    } catch (_) {
      return '';
    }
  };

  const latestAssistantMessage = () => {
    try {
      const context = hostWindow.SillyTavern?.getContext?.();
      if (Array.isArray(context?.chat)) {
        for (let id = context.chat.length - 1; id >= 0; id--) {
          const row = context.chat[id];
          if (row && !row.is_user && !row.is_system) return { message_id: id, swipe_id: row.swipe_id ?? 0 };
        }
        return null;
      }
      const rows = getChatMessages('0-{{lastMessageId}}', { role: 'assistant', hide_state: 'unhidden', include_swipes: true });
      return rows.at(-1) || null;
    } catch (_) {
      return null;
    }
  };

  const findMessageText = (messageId) => hostDocument.querySelector(`.mes[mesid="${messageId}"] .mes_text`);

  const clearHud = () => {
    hostDocument.querySelectorAll(`[${HUD_ATTR}]`).forEach(node => node.remove());
  };

  const messageKey = message => [
    currentChatId(),
    message?.message_id ?? '',
    message?.swipe_id ?? message?.swipeId ?? message?.swipe ?? '',
  ].join(':');

  const targetIsCurrent = key => {
    const latest = latestAssistantMessage();
    return Boolean(latest && messageKey(latest) === key);
  };

  const showSyncing = message => {
    clearHud();
    const textNode = findMessageText(message?.message_id);
    if (!textNode) return false;
    const notice = createEl('section', 'xhcs-hud');
    notice.setAttribute(HUD_ATTR, 'v1');
    notice.dataset.messageId = String(message.message_id);
    notice.setAttribute('role', 'status');
    notice.append(createEl('span', 'xhcs-empty', '正在等待本楼状态同步。'));
    textNode.insertAdjacentElement('afterend', notice);
    return true;
  };

  const observeTargetDom = (key, messageId) => {
    state.targetObserver?.disconnect();
    const Observer = hostWindow.MutationObserver || window.MutationObserver;
    if (typeof Observer !== 'function' || !hostDocument.body) return;
    state.targetObserver = new Observer(records => {
      if (!targetIsCurrent(key)) {
        state.targetObserver?.disconnect();
        state.targetObserver = null;
        return;
      }
      const relevant = records.some(record => [...record.addedNodes].some(node => {
        if (node.nodeType !== 1 || node.matches?.(`[${HUD_ATTR}]`) || node.closest?.(`[${HUD_ATTR}]`)) return false;
        return node.matches?.(`.mes[mesid="${messageId}"]`) || node.querySelector?.(`.mes[mesid="${messageId}"]`)
          || node.matches?.(`.mes[mesid="${messageId}"] .mes_text`) || node.querySelector?.(`.mes[mesid="${messageId}"] .mes_text`);
      }));
      if (relevant) {
        state.targetObserver.disconnect();
        state.targetObserver = null;
        scheduleRender(0);
      }
    });
    state.targetObserver.observe(hostDocument.body, { childList: true, subtree: true });
    state.observers.push(state.targetObserver);
  };

  const scheduleRender = (delay = 80, resetRetries = true) => {
    if (!state.ready) return;
    if (resetRetries) state.retryIndex = 0;
    if (state.refreshing) {
      state.pendingRefresh = true;
      return;
    }
    hostWindow.clearTimeout(state.timer);
    state.timer = hostWindow.setTimeout(() => void render(), delay);
  };

  const render = async () => {
    if (!state.ready) return;
    if (state.refreshing) {
      state.pendingRefresh = true;
      return;
    }
    state.refreshing = true;
    state.pendingRefresh = false;
    try {
      const chatKey=currentChatId();
      if(state.atlasChatKey!==chatKey){hostDocument.querySelectorAll('.xhcs-map-dialog,.xhcs-rank-dialog,.xhcs-character-dialog').forEach(d=>d.close());state.atlasCameras={};state.atlasMode='world';state.atlasChatKey=chatKey;}
      const message = latestAssistantMessage();
      if (!message) {
        clearHud();
        return;
      }
      const key = messageKey(message);
      if (key !== state.targetKey) {
        state.generation += 1;
        state.targetKey = key;
        state.retryIndex = 0;
        state.signature = '';
        state.targetObserver?.disconnect();
        state.targetObserver = null;
      }
      const generation = state.generation;
      const data = await window.Mvu?.getMvuData?.({ type: 'message', message_id: message.message_id });
      if (!data?.stat_data) {
        if (targetIsCurrent(key)) {
          showSyncing(message);
          observeTargetDom(key, message.message_id);
          scheduleRetry(key, generation);
        }
        return;
      }
      if (data.stat_data?.元数据?.开局完成 !== true) {
        clearHud();
        return;
      }

      const textNode = findMessageText(message.message_id);
      if (!textNode) {
        clearHud();
        observeTargetDom(key, message.message_id);
        scheduleRetry(key, generation);
        return;
      }
      if (generation !== state.generation || !targetIsCurrent(key)) return;
      let panel = textNode.parentElement.querySelector(`[${HUD_ATTR}]`);
      hostDocument.querySelectorAll(`[${HUD_ATTR}]`).forEach(node => { if (node !== panel) node.remove(); });
      if (!panel || panel.dataset.messageId !== String(message.message_id)) {
        clearHud();
        panel = createEl('section', 'xhcs-hud');
        panel.setAttribute(HUD_ATTR, 'v1'); panel.dataset.messageId = String(message.message_id);
        panel.setAttribute('aria-label', '香火成神系统状态');
        panel.innerHTML = staticShell(); bindNavigation(panel, message.message_id); bindTheme(panel);
        textNode.insertAdjacentElement('afterend', panel);
      }
      if (!panel.querySelector('[data-role=power]')) { panel.innerHTML = staticShell(); bindNavigation(panel, message.message_id); bindTheme(panel); }
      const signature = `${key}:${JSON.stringify(data.stat_data)}`;
      if (signature === state.signature && panel.dataset.rendered === 'true') return;
      const expanded = new Set([...panel.querySelectorAll('details[open][data-key]')].map(node => node.dataset.key));
      const active = hostDocument.activeElement;
      const focusedKey = active?.closest('details[data-key]')?.dataset.key;
      renderHud(panel, data.stat_data);
      panel.querySelectorAll('details[data-key]').forEach(node => {
        node.open = expanded.has(node.dataset.key);
        if (focusedKey === node.dataset.key) node.querySelector('summary')?.focus({ preventScroll: true });
      });
      panel.dataset.rendered = 'true'; state.signature = signature;
      state.retryIndex = 0;
      state.targetObserver?.disconnect();
      state.targetObserver = null;
    } catch (error) {
      clearHud();
      console.error('[香火成神] 状态栏渲染失败', error);
      const textNode = findMessageText(latestAssistantMessage()?.message_id);
      if (textNode) {
        const panel = hostDocument.createElement('div');
        panel.className = 'xhcs-hud';
        panel.setAttribute(HUD_ATTR, 'v1');
        panel.append(createEl('span', 'xhcs-empty xhcs-hud-error', '状态栏同步失败，正文与变量不受影响。'));
        textNode.insertAdjacentElement('afterend', panel);
      }
    } finally {
      state.refreshing = false;
      if (state.pendingRefresh) scheduleRender(0, false);
    }
  };

  const scheduleRetry = (key, generation) => {
    const delays = [0, 100, 250, 500, 1000, 2000];
    if (state.retryIndex >= delays.length) return;
    const delay = delays[state.retryIndex++];
    hostWindow.clearTimeout(state.timer);
    state.timer = hostWindow.setTimeout(() => {
      if (generation !== state.generation || !targetIsCurrent(key)) return;
      scheduleRender(0, false);
    }, delay);
  };

  const bind = async () => {
    injectStyle();
    if (typeof waitGlobalInitialized === 'function') {
      await waitGlobalInitialized('Mvu');
    } else {
      const startedAt = Date.now();
      while (!window.Mvu && Date.now() - startedAt < 10000) {
        await new Promise(resolve => setTimeout(resolve, 100));
      }
    }
    state.ready = Boolean(window.Mvu);
    if (!state.ready) {
      console.warn('[香火成神] MVU 未就绪，状态栏暂不启用');
      return;
    }

    // Native host events also cover generation performed outside helper wrappers.
    const context = hostWindow.SillyTavern?.getContext?.();
    if (context?.eventSource && context.eventTypes) {
      ['MESSAGE_RECEIVED', 'CHARACTER_MESSAGE_RENDERED', 'GENERATION_ENDED', 'GENERATION_STOPPED', 'MESSAGE_UPDATED', 'MESSAGE_SWIPED', 'CHAT_CHANGED'].forEach(name => {
        const event = context.eventTypes[name];
        if (!event) return;
        const listener = () => scheduleRender(0);
        context.eventSource.on(event, listener);
        state.disposers.push(() => context.eventSource.removeListener(event, listener));
      });
    }
    const chat = hostDocument.getElementById('chat');
    if (chat && hostWindow.MutationObserver) {
      const observer = new hostWindow.MutationObserver(records => {
        if (records.some(record => !record.target.closest?.(`[${HUD_ATTR}]`) && [...record.addedNodes].some(node => node.nodeType === 1 && !node.matches?.(`[${HUD_ATTR}]`) && (node.matches?.('.mes, .mes_text') || node.querySelector?.('.mes, .mes_text'))))) scheduleRender(0);
      });
      observer.observe(chat, { childList: true, subtree: true });
      state.observers.push(observer);
    }

    const on = window.eventOn || hostWindow.eventOn;
    const events = window.tavern_events || hostWindow.tavern_events || {};
    if (typeof on === 'function') {
      [
        events.CHARACTER_MESSAGE_RENDERED,
        events.MESSAGE_RECEIVED,
        events.GENERATION_STOPPED,
        events.MESSAGE_UPDATED,
        events.MESSAGE_SWIPED,
        events.MESSAGE_EDITED,
        events.CHAT_CHANGED,
        events.GENERATION_ENDED,
      ].filter(Boolean).forEach(eventName => {
        const disposer = on(eventName, () => scheduleRender());
        if (disposer?.stop) state.disposers.push(() => disposer.stop());
      });

      [window.Mvu?.events?.VARIABLE_UPDATE_ENDED, window.Mvu?.events?.VARIABLE_INITIALIZED]
        .filter(Boolean)
        .forEach(eventName => {
          const disposer = on(eventName, () => scheduleRender(120));
          if (disposer?.stop) state.disposers.push(() => disposer.stop());
        });
    }

    scheduleRender(0);
  };

  window.addEventListener('pagehide', () => {
    state.ready = false;
    state.generation += 1;
    hostWindow.clearTimeout(state.timer);
    state.targetObserver?.disconnect();
    state.targetObserver = null;
    state.observers.forEach(observer => observer.disconnect());
    clearHud();
    hostDocument.getElementById(STYLE_ID)?.remove();
    state.disposers.forEach(dispose => {
      try {
        dispose();
      } catch (_) {
        // Ignore teardown errors.
      }
    });
  }, { once: true });

  await bind();
})();
